sys_script_include.script:
var MoveworksBuilder = Class.create();
MoveworksBuilder.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    /**
     * AJAX entry point — called from widget client script via c.server.get.
     * sysparm_request : natural language request from the user
     * Returns JSON string of the generated Moveworks object.
     */
    buildObject: function() {
        var userRequest = this.getParameter('sysparm_request');
        if (!userRequest) {
            return JSON.stringify({ error: 'No request provided' });
        }
        var api = new x_146833_movewor_0.MoveworksAPI();
        return api.callClaudeAPI(userRequest);
    },

    type: 'MoveworksBuilder'
});
